mapper.select:
SELECT INTG_IMG_FILE_PATH_NM
FROM ODS.S_MRDDRIMD
WHERE MDRC_ID = #{mdrcId}
AND MDRC_FOM_SEQ = #{mdrcFomSeq}
ORDER BY INTG_IMG_FILE_PATH_NM

SELECT MDFM_ID            AS mdfmId,
       MDFM_FOM_SEQ       AS mdfmFormSeq,
       MDFM_SCTN_SEQ      AS mdfmSctnSeq,
       SCTN_DGN_META_LDAT AS sctnDgnMetaLdat
FROM ODS.S_MRFMFSCD
WHERE MDFM_CLS_CD = #{mdfmClsCd}
  AND MDFM_ID = #{mdfmId}
  AND MDFM_FOM_SEQ = #{mdfmFomSeq}
ORDER BY MDFM_ID, MDFM_FOM_SEQ, MDFM_SCTN_SEQ
